\begin{itemize}
\item The $P$-components of a $T$-net are its elementary circuits.

\item In a $T$-system an enabled transition can lose its enabledness only by firing itself. During the firing of an occurrence sequence the token count of a path
$(p_{in},...,p_{out})$ joining two places can change only by creating tokens at $p_{in}$ or consuming tokens at $p_{out}$. The token count of a circuit is the same for each reachable marking.
\end{itemize}

\label{rem_existencestructuredynamics}
Consider a well-formed free-choice net $N$.
\begin{enumerate}
\item \emph{Existence}: If $N$ is not a $T$-net then $N$ has a $CP$-subnet $\hat{N} \subset N$, \mbox{\cite[Prop. 7.11]{DE1995}}. One may even assume that a given transition $t\in N$ is not contained \mbox{in $\hat{N}$}, \cite[Lem. 1.2]{Wehler2010}. The latter result is crucial to obtain in Theorem \ref{theor_existencecpexhaustion} a $CP$-exhaustion of $N$ which is adapted to a given regeneration cluster of $N$.

\item \emph{Structure}: A $CP$-subnet $\hat{N} \subset N$ has the following structural properties:

\begin{itemize}
\item The net $\hat{N}$ has a unique way-in transition $t_{in} \in \hat{N}_T$, \mbox{\cite[Prop. 7.10]{DE1995}}. The net $\hat{N}$ has at least one way-out transition $t_{out}$ because $N$ is strongly connected.\vspace*{0.8mm}

\item Each place $p \in \hat{N}$ has a path $(t_{in},...,p) \subset \hat{N}$ leading from $t_{in}$ to $p$, cf. \mbox{\cite[Prop. 7.10 proof]{DE1995}}.\vspace*{0.8mm}

\item The complement $\overline{N}:=N\setminus \hat{N}$ is a well-formed free-choice net too, \cite[Cor. 7.9]{DE1995}.\vspace*{0.8mm}

\item Each cluster $cl \subset N$ satisfies
$$cl \not\subset \hat{N} \iff (cl \cap \overline{N})_T \neq \emptyset \iff cl_P \subset \overline{N}_P$$
The proof uses that $\overline{N}$ is strongly connected and that $\hat{N} \subset N$ is transition-bordered.
\end{itemize}

\item \emph{Dynamics}: Consider a $CP$-subnet $\hat{N} \subset N$, and a live and bounded marking $\mu_0$ of $N$ and a reachable marking $\mu$ of $(N,\mu_0)$.

\begin{itemize}
\item There exists a \emph{shutdown sequence} for $\hat{N}$, i.e. a finite occurrence sequence \mbox{of $(N,\mu)$}
$$\mu \xrightarrow{\sigma_{sd}} \mu_{sd}$$
with transitions $t\in \sigma_{sd}$ only from $\hat{N}_T\setminus \{t_{in}\}$, such that $\mu_{sd}$ enables no transition of $\hat{N}$ different from $t_{in}$, \cite[Prop. 7.8]{DE1995}.

\item The free-choice system
$$(\overline{N},\overline{\mu}_{sd}) \text{ with } \overline{\mu}_{sd}:=\mu_{sd}|\overline{N}$$
is live and bounded, \cite[Prop. 7.8]{DE1995}. If $(N,\mu_0)$ is safe then $(\overline{N},\overline{\mu}_{sd})$ is safe too.

\item An occurrence sequence of transitions from $\overline{N}$ is enabled at a marking $\mu$ \mbox{of $N$} iff it is enabled as an occurrence sequence of  the restriction $(\overline{N},\mu|\overline{N})$.
\end{itemize}
\end{enumerate}

i) \emph{Algorithm constructing the exhaustion}: The following algorithm constructs the index \mbox{set $I \subset \mathbb{N}$} and the family ${(\hat{N}_i)}_{i \in I}$ of the $CP$-exhaustion by induction on $j \geq 0$:
\begin{flushleft}
Initialize the net $\overline{N}_{-1}:=N$ and the cluster $cl_{-1}:=cl \subset \overline{N}_{-1}$.
\end{flushleft}
\begin{flushleft}
Step $\mathfrak{A}(j)$ constructs a triple $(\hat{N}_j,\ \overline{N}_j,\ cl_j)$ with the following properties
\end{flushleft}
\begin{itemize}
\item The first component $\hat{N}_{j}$ is a $cl_{j-1}$-adapted $CP$-subnet $\hat{N}_{j} \subset \overline{N}_{j-1}$.
\item Second component: The complement $\overline{N}_{j}:=\overline{N}_{j-1} \setminus \hat{N}_j$ is well-formed.
\item Third component: The cluster $cl_j:=cl_{j-1} \cap \overline{N}_j$ is not empty .
\end{itemize}
\begin{flushleft}
Induction start $\mathfrak{A}(0)$: If $N$ is a $T$-net then set
\end{flushleft}
$$I:=\emptyset,\ \overline{N}:=N$$
and terminate. Otherwise Remark \ref{rem_existencestructuredynamics} provides a $cl$-adapted $CP$-subnet
$$\hat{N}_0 \subset N$$
Define
$$\overline{N}_0:=N \setminus \hat{N}_0 \text{ and } cl_{0}:=cl \cap \overline{N}_0 \neq \emptyset$$
Remark \ref{rem_existencestructuredynamics}, part 2) shows that $\overline{N}_0$ is well-formed.
\begin{flushleft}
Induction step $j \mapsto j+1$: By induction assumption $\mathfrak{A}(j)$ the free-choice net $\overline{N}_{j}$ is well-formed. If $\overline{N}_{j}$ is a $T$-net, then set
$$I:=\{0,...,j-1\} \text{ and } \overline{N}:=\overline{N}_j$$
and terminate. Otherwise Remark \ref{rem_existencestructuredynamics} provides a $cl_j$-adapted $CP$-subnet
$$\hat{N}_{j+1} \subset \overline{N}_j$$
Define
$$\overline{N}_{j+1}:=\overline{N}_j\setminus \hat{N}_{j+1} \text{ and } cl_{j+1}:=cl_j \cap \overline{N}_{j+1} \neq \emptyset$$
\end{flushleft}

\noindent
ii) \emph{Correctness}: The algorithm terminates because $N$ is finite. If $N$ is not a $T$-net then the iterative application of Proposition \ref{prop_iterationcpsubnet} implies that for each $j\in I$ the $CP$-subnet
$$\hat{N}_{j} \subset \overline{N}_{j-1}$$
is also a $CP$-subnet $\hat{N}_{j} \subset N$. Also $cl  \not\subset \hat{N}_j$ because by construction
$$cl \cap \overline{N}_{j}=cl_{j-1} \cap \overline{N}_{j} \neq \emptyset$$

