\begin{enumerate}
\item \emph{Constructing an adapted $CP$-exhaustion}:
\begin{itemize}
\item First, choose the $CP$-subnet of $N$
$$\hat{N}_0:=span_N<p_4,t_1,t_4>\ \subset N$$
The complement
$$\overline{N}_0:=N \setminus \hat{N}_0$$
is well-formed.
\eject
\item Secondly, choose the $CP$-subnet of the complement $\overline{N}_0$
$$\hat{N}_1:= span_{\overline{N}_0}<p_5,t_2,t_5>\ \subset \overline{N}_0$$
\item The final complement is the strongly connected $T$-net
$$\overline{N}:=\overline{N}_0 \setminus \hat{N}_1$$
\end{itemize}

\noindent Figure \ref{fig_cpexhaustion} shows the subnets $\hat{N}_0,\ \hat{N}_1,\ \overline{N} \subset N$. The family $(\hat{N}_0,\hat{N}_1)$ is a $cl$-adapted $CP$-exhaustion of $N$, and
$$N_{exh}:=\overline{N}\ \dot \cup \ \hat{N}_0\ \dot\cup \ \hat{N}_1$$
satisfies
$$span_N<N_{exh}>=N.$$

\noindent Note: The $CP$-exhaustion is also adapted to the cluster
$$cl_1=span_N<p_1,p_2,t_1,t_2,t_8>.$$
\item \emph{Greediness of the clusters}: Both clusters $cl$ and $cl_1$ of $N$ are greedy in the Petri \mbox{net $(N,\mu_0)$}. They provide examples of \emph{regeneration clusters}, a fundamental concept which will be introduced in Definition \ref{def_perpetual}.
\end{enumerate}

\label{def_perpetual}
\begin{enumerate}
\item A Petri net $(N,\mu_0)$ is \emph{lucent} if for any pair $(\mu_1,\mu_2)$ of reachable markings
$$en(N,\mu_1)=en(N,\mu_2) \implies \mu_1=\mu_2.$$
\item A Petri net $(N,\mu_0)$ is \emph{perpetual} if it is live and bounded and there exists a \mbox{cluster $cl \subset N$} such that $\mu_{cl}$ is a home marking of $(N,\mu_0)$. The cluster $cl$ is named a \emph{regeneration cluster} of $(N,\mu_0)$, and $\mu_{cl}$ is a \emph{regeneration marking} of $(N,\mu_0)$.
\end{enumerate}

\label{def_enablingequivalence}
A pair of reachable markings $(\mu_1,\mu_2)$ of a Petri net $(N,\mu_0)$ is \emph{enabling equivalent} if
$$en(N,\mu_1)=en(N,\mu_2)$$

