\label{prop_perpetualtsystem}
Let $(TN,\mu)$ be a $T$-system. For each transition $t\in TN_T$ and pre-place $q \in\ ^\bullet t$ \mbox{with $\mu(q)=0$} denote by
$$en(TN,\mu)_q:=\left\{(\tau,\delta):\ \tau \in en(TN,\mu),\ \delta=(\tau,...,q,t) \subset TN \text{ elementary}\right\}$$
the set of all enabled transitions $\tau$ together with their elementary paths to $t$, which \mbox{pass $q$}.
\begin{enumerate}
\item \emph{General $T$-system}: Consider an arbitrary \mbox{transition $t\in TN_T$} which is enabled at $\mu$. For each pre-place $q \in\ ^\bullet t \text{ with } \mu(q)=0$ exists a pair
$$(\tau,\delta) \in en(TN,\mu)_q \text{ with } \Vert \mu \Vert_\delta =0.$$
\item \emph{Perpetual $T$-system}: Assume that $(TN,\mu)$ is even perpetual with regeneration cluster $cl$ and denote \mbox{by $t_{cl}$} the unique transition of $cl$.
\begin{flushleft}
i) For each transition $t\in TN_T$ with a pre-place $p\in \ ^\bullet t$ with $\mu(p)=1$ exists for each \mbox{pre-place $q \in\ ^\bullet t$} with $\mu(q)=0$ a pair
$$(\tau,\delta) \in en(TN,\mu)_q \text{ with } \Vert \mu \Vert_\delta =0 \text{ and } t_{cl} \notin \delta_{seg}$$
for the segment $\delta_{seg}:=(\tau,...,q)$ of $\delta$.

ii) Each elementary path $\delta \subset TN$ with $t_{cl} \notin \delta$ has token count $\Vert \mu \Vert_\delta \leq 1$.
\end{flushleft}
\end{enumerate}

\label{prop_tsystemlucent}
Consider a \mbox{perpetual $T$-system $(TN,\mu_0)$} with regeneration cluster $cl$. For each pair $(\mu_1,\mu_2)$ of reachable markings of $(TN,\mu_0)$ enabling equivalence implies marking equality, i.e.
$$en(TN,\mu_1)=en(TN,\mu_2) \implies \mu_1=\mu_2$$

\label{prop_cpnetsubnetsperpetual}
Consider a perpetual free-choice system $(N,\mu_0)$ with a regeneration cluster $cl \subset N$. Let $\hat{N} \subset N$ be a \mbox{a $cl$-adapted} $CP$-subnet.
\begin{enumerate}
\item The $CP$-subnet $\hat{N}$ has no circuits. In particular, each path in $\hat{N}$\ is elementary.
\end{enumerate}
In addition, let $\mu$ be an arbitrary reachable marking \mbox{of $(N,\mu_0)$} and set $\hat{\mu}:=\mu|\hat{N}$.
\begin{enumerate}\addtocounter{enumi}{1}
\item Each path $\delta \subset \hat{N}$ has token count $\Vert \mu \Vert_\delta \leq 1$.

\item Firing a shutdown sequence of $\hat{N}$
$$\mu \xrightarrow{\sigma_{sd}} \mu_{sd}$$
removes all tokens from $\hat{N}$, i.e.
$$\mu_{sd}|\hat{N}=0$$
\item Each transition $t\in \hat{N}$ with a path $(p,...,t) \subset \hat{N},\ p \in \hat{N}_P$ \mbox{and $\hat{\mu}(p)=1$}, can be enabled by firing an occurrence sequence of $(\hat{N},\hat{\mu})$
$$\hat{\mu} \xrightarrow{\sigma} \hat{\mu}_{post} \text{ with } t_{in} \notin \sigma.$$
\end{enumerate}

